CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING ((select auth.uid())=id);
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING ((select auth.uid())=id) WITH CHECK ((select auth.uid())=id);
CREATE TABLE public.account_state (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, favorites jsonb NOT NULL DEFAULT '[]', alerts jsonb NOT NULL DEFAULT '[]', pro_demo boolean NOT NULL DEFAULT false, whatsapp_alerts boolean NOT NULL DEFAULT true, search_day date NOT NULL DEFAULT current_date, searches_used integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.account_state TO authenticated;
GRANT ALL ON public.account_state TO service_role;
ALTER TABLE public.account_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY account_read_own ON public.account_state FOR SELECT TO authenticated USING ((select auth.uid())=user_id);
CREATE POLICY account_insert_own ON public.account_state FOR INSERT TO authenticated WITH CHECK ((select auth.uid())=user_id);
CREATE POLICY account_update_own ON public.account_state FOR UPDATE TO authenticated USING ((select auth.uid())=user_id) WITH CHECK ((select auth.uid())=user_id);
CREATE FUNCTION public.touch_account_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_account_updated_at();
CREATE TRIGGER account_updated BEFORE UPDATE ON public.account_state FOR EACH ROW EXECUTE FUNCTION public.touch_account_updated_at();
CREATE FUNCTION public.create_chronoparts_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); INSERT INTO public.account_state(user_id) VALUES (NEW.id); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.create_chronoparts_profile() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER chronoparts_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_chronoparts_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,coalesce(raw_user_meta_data->>'display_name','') FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.account_state(user_id) SELECT id FROM public.profiles ON CONFLICT DO NOTHING;